export const countries={
 brazil:{name:'Brazil',local:'Brasil',flag:'br',center:[-52,-13],bounds:[[-74,-34],[-34,6]],color:'#dcebd9'},
 uruguay:{name:'Uruguay',local:'',flag:'uy',center:[-56,-33],bounds:[[-59,-35.5],[-53,-30]],color:'#e0edf4'},
 argentina:{name:'Argentina',local:'',flag:'ar',center:[-65,-39],bounds:[[-74,-56],[-53,-21]],color:'#dfebf3'}
};
export function createSouthAmerica(map,host){
 let data,loading,active=null,labels=[];
 const sidebar=document.createElement('aside');sidebar.className='sidebar south-america-sidebar';sidebar.hidden=true;
 sidebar.setAttribute('aria-label','Explore South America');
 sidebar.innerHTML='<div class="sidebar-scroll"><div class="selection-top"><span class="eyebrow">SOUTH AMERICA</span><img width="40" height="30" alt=""></div><h2></h2><p class="country-local"></p><p class="preview-note">Country preview · subdivisions coming next.</p><nav aria-label="South American countries" class="south-america-countries"></nav><a class="quiet-button" href="#china">Back to East Asia ↗</a></div><footer class="sidebar-footer"><a href="data/flight-context-sources.json" target="_blank" rel="noopener">Boundary source</a><span>Created by Ethan Hu</span></footer>';
 document.querySelector('.workspace').insertBefore(sidebar,document.getElementById('map-shell'));
 const nav=sidebar.querySelector('nav');for(const [id,c] of Object.entries(countries)){const b=document.createElement('button');b.className='search-result';b.textContent=c.name;b.onclick=()=>host.switchAtlas(id);b.dataset.country=id;nav.append(b);}
 const arrow=document.createElement('button');arrow.className='continent-flight';arrow.type='button';arrow.setAttribute('aria-label','Fly to South America');arrow.title='Fly to South America';arrow.innerHTML='<span aria-hidden="true">↙</span><span class="flight-caption">South America</span>';document.getElementById('map-shell').append(arrow);
 let lastAsia='china';arrow.onclick=()=>{if(host.isBusy())return;const current=host.country();if(!countries[current]){lastAsia=current;host.switchAtlas('brazil',true,true);}else host.switchAtlas(lastAsia,true,true);};
 function syncArrow(){arrow.hidden=!window.AtlasDev.enabled;const south=!!countries[host.country()];arrow.querySelector('[aria-hidden]').textContent=south?'↗':'↙';arrow.querySelector('.flight-caption').textContent=south?'East Asia':'South America';arrow.setAttribute('aria-label',south?'Fly to East Asia':'Fly to South America');arrow.title=arrow.getAttribute('aria-label');}
 function syncDeveloper(){syncArrow();for(const id of ['flight-world','south-america-fill','south-america-lines'])if(map.getLayer(id))map.setLayoutProperty(id,'visibility',window.AtlasDev.enabled?'visible':'none');if(!window.AtlasDev.enabled)clearLabels();}
 syncArrow();
 function clearLabels(){labels.forEach(l=>l.remove());labels=[];}
 function updateLabels(){clearLabels();if(!active||map.isMoving())return;for(const [id,c] of Object.entries(countries)){const el=document.createElement('div');el.className='province-label';el.textContent=c.name;el.style.cursor='pointer';el.onclick=e=>{e.stopPropagation();host.switchAtlas(id);};labels.push(new maplibregl.Marker({element:el}).setLngLat(c.center).addTo(map));}}
 async function warm(){if(!window.AtlasDev.enabled)throw Error('Developer mode is required');if(data)return;if(loading)return loading;loading=(async()=>{const r=await fetch('data/flight-context.bin');if(!r.ok)throw Error('Country preview unavailable');data=await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).json();map.addSource('flight-context',{type:'geojson',data,tolerance:.5,attribution:'Country silhouettes: <a href="https://www.naturalearthdata.com/downloads/110m-cultural-vectors/110m-admin-0-countries/" target="_blank" rel="noopener">Natural Earth</a>'});map.addLayer({id:'flight-world',type:'fill',source:'flight-context',maxzoom:4,paint:{'fill-color':'#d7d7d3','fill-opacity':['interpolate',['linear'],['zoom'],2,1,4,0],'fill-antialias':false}},'china-context');map.addLayer({id:'south-america-fill',type:'fill',source:'flight-context',filter:['!=',['get','country'],''],paint:{'fill-color':['match',['get','country'],...Object.entries(countries).flatMap(([id,c])=>[id,c.color]),'#d7d7d3']}});map.addLayer({id:'south-america-lines',type:'line',source:'flight-context',filter:['!=',['get','country'],''],paint:{'line-color':'#9aaba5','line-width':1}});map.on('click',e=>{const hit=map.queryRenderedFeatures(e.point,{layers:['south-america-fill']})[0];if(hit&&!host.isBusy())host.switchAtlas(hit.properties.country);});syncDeveloper();})();try{await loading;}catch(e){loading=null;data=null;throw e;}}
 map.on('moveend',updateLabels);
 function portal(id){const c=countries[id];return{bounds:c.bounds,get ready(){return !!data;},warm,async enter(){active=id;sidebar.hidden=false;sidebar.querySelector('h2').textContent=c.name;sidebar.querySelector('.country-local').textContent=c.local;const flag=sidebar.querySelector('img');flag.src='vendor/flag-'+c.flag+'.svg';flag.alt='Flag of '+c.name;for(const b of nav.children)b.setAttribute('aria-current',String(b.dataset.country===id));for(const key of ['mode-province','mode-prefecture','mode-lock'])document.getElementById(key).hidden=true;document.getElementById('map-hint').textContent='Select Brazil, Uruguay or Argentina';updateLabels();syncArrow();},leave(){active=null;sidebar.hidden=true;clearLabels();for(const key of ['mode-province','mode-prefecture','mode-lock'])document.getElementById(key).hidden=false;},updateLabels,pauseLabels:clearLabels,getSelection:()=>null,restore:async()=>{},setMode(){},home:()=>host.fit(c.bounds),viewParent:()=>host.fit(c.bounds),random:()=>host.switchAtlas(Object.keys(countries)[Math.floor(Math.random()*3)])};}
 async function fly(bounds){await warm();const target=map.cameraForBounds(bounds,{padding:45,maxZoom:6});if(!target)return;return new Promise(resolve=>{map.once('moveend',resolve);map.flyTo({...target,duration:2800,curve:1.65,minZoom:.65,retainPadding:false,essential:false,easing:t=>t*t*(3-2*t)});});}
 return{portals:Object.fromEntries(Object.keys(countries).map(id=>[id,portal(id)])),fly,syncArrow,syncDeveloper};
}
